import type { Lang } from "@/lib/dashLang";

// Static (non-computed) strings for the BOD PDF (bodReportPdf.tsx). The
// narrative/insight SENTENCES (which interpolate numbers into full
// sentences) are generated by language-specific functions further down
// rather than a flat dictionary — EN and JP restructure those sentences
// rather than substituting words 1:1 into the Indonesian word order.
export function tf(str: string, vars: Record<string, string | number>): string {
  return str.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ""));
}

