/* ============ narrative generators (full sentences, not word-swaps) ============ */

type Kpis = { sales: number; gmv: number; traffic: number; in_cart: number; ad_cost: number; roas: number | null };

export function buildNarrative(
  lang: Lang, cur: Kpis, prev: Kpis | null, periodLabel: string, scopeLabel: string,
  fmt: { rp: (n: number) => string; pct: (n: number) => string; roasFmt: (n: number | null | undefined) => string; cnt: (n: number) => string },
  pctDelta: (cur: number, prev: number | null | undefined) => number | null,
): string {
  const dSales = pctDelta(cur.sales, prev?.sales);
  const dAds = pctDelta(cur.ad_cost, prev?.ad_cost);
  const share = cur.gmv > 0 ? (cur.sales / cur.gmv) * 100 : null;
  const atc = cur.traffic > 0 ? (cur.in_cart / cur.traffic) * 100 : 0;
  const { rp, pct, roasFmt, cnt } = fmt;

  if (lang === "en") {
    const parts: string[] = [];
    parts.push(`In ${periodLabel}, Panasonic sales in ${scopeLabel} reached ${rp(cur.sales)}${dSales != null ? ` — ${dSales >= 0 ? "up" : "down"} ${pct(Math.abs(dSales))} vs the prior period` : ""}.`);
    if (dAds != null && dSales != null) {
      parts.push(dAds < 0 && dSales > 0
        ? `This growth was efficient: ad spend actually fell ${pct(Math.abs(dAds))} to ${rp(cur.ad_cost)}, putting ROAS at ${roasFmt(cur.roas)}.`
        : `Ad spend ${dAds >= 0 ? "rose" : "fell"} ${pct(Math.abs(dAds))} to ${rp(cur.ad_cost)}, with ROAS at ${roasFmt(cur.roas)}.`);
    } else {
      parts.push(`Ad spend was ${rp(cur.ad_cost)} with ROAS at ${roasFmt(cur.roas)}.`);
    }
    parts.push(`The funnel logged ${cnt(cur.traffic)} product visits and ${cnt(cur.in_cart)} add-to-carts (a ${pct(atc)} ratio).`);
    if (share != null) parts.push(`Panasonic accounted for ${pct(share)} of total dealer store sales (${rp(cur.gmv)}).`);
    return parts.join(" ");
  }
  if (lang === "jp") {
    const parts: string[] = [];
    parts.push(`${periodLabel}、${scopeLabel}におけるパナソニックの売上は${rp(cur.sales)}に達し${dSales != null ? `、前期比${dSales >= 0 ? "増加" : "減少"}${pct(Math.abs(dSales))}となりました` : "ました"}。`);
    if (dAds != null && dSales != null) {
      parts.push(dAds < 0 && dSales > 0
        ? `この成長は効率的なもので、広告費はむしろ${pct(Math.abs(dAds))}減少して${rp(cur.ad_cost)}となり、ROASは${roasFmt(cur.roas)}となりました。`
        : `広告費は${pct(Math.abs(dAds))}${dAds >= 0 ? "増加" : "減少"}して${rp(cur.ad_cost)}となり、ROASは${roasFmt(cur.roas)}です。`);
    } else {
      parts.push(`広告費は${rp(cur.ad_cost)}、ROASは${roasFmt(cur.roas)}でした。`);
    }
    parts.push(`ファネルでは${cnt(cur.traffic)}件の商品訪問と${cnt(cur.in_cart)}件のカート追加を記録しました（比率${pct(atc)}）。`);
    if (share != null) parts.push(`パナソニックは販売店の総売上（${rp(cur.gmv)}）のうち${pct(share)}を占めています。`);
    return parts.join("");
  }
  // id (default)
  const parts: string[] = [];
  parts.push(`Pada ${periodLabel}, penjualan Panasonic di ${scopeLabel} mencapai ${rp(cur.sales)}${dSales != null ? ` — ${dSales >= 0 ? "naik" : "turun"} ${pct(Math.abs(dSales))} dibanding periode sebelumnya` : ""}.`);
  if (dAds != null && dSales != null) {
    parts.push(dAds < 0 && dSales > 0
      ? `Pertumbuhan ini efisien: biaya iklan justru turun ${pct(Math.abs(dAds))} menjadi ${rp(cur.ad_cost)}, sehingga ROAS berada di ${roasFmt(cur.roas)}.`
      : `Biaya iklan ${dAds >= 0 ? "naik" : "turun"} ${pct(Math.abs(dAds))} menjadi ${rp(cur.ad_cost)}, dengan ROAS ${roasFmt(cur.roas)}.`);
  } else {
    parts.push(`Biaya iklan tercatat ${rp(cur.ad_cost)} dengan ROAS ${roasFmt(cur.roas)}.`);
  }
  parts.push(`Funnel mencatat ${cnt(cur.traffic)} kunjungan produk dan ${cnt(cur.in_cart)} tambah-ke-keranjang (rasio ${pct(atc)}).`);
  if (share != null) parts.push(`Panasonic menyumbang ${pct(share)} dari total penjualan toko dealer (${rp(cur.gmv)}).`);
  return parts.join(" ");
}

export type InsightCardData = { tone: "win" | "insight" | "watch"; title: string; body: string };

export function buildInsightCards(
  lang: Lang, dSales: number | null, dAds: number | null, dGmv: number | null,
  k: Kpis, atcRate: number, shareFrac: number, dealersLen: number, weak: number,
  fmt: { rp: (n: number) => string; pct: (n: number) => string; roasFmt: (n: number | null | undefined) => string; cnt: (n: number) => string },
): InsightCardData[] {
  const { rp, pct, roasFmt, cnt } = fmt;
  const cards: InsightCardData[] = [];

  if (lang === "en") {
    if (dSales != null && dAds != null && dSales > 0 && dAds < 0) {
      cards.push({ tone: "win", title: "Sales up, spend down", body: `Sales grew ${pct(dSales)} while ad spend fell ${pct(Math.abs(dAds))}. Demand is becoming more organic and the ad budget is working more efficiently — ROAS at ${roasFmt(k.roas)}.` });
    } else if (dSales != null && dSales > 0) {
      cards.push({ tone: "win", title: "Sales growing", body: `Panasonic sales rose ${pct(dSales)} to ${rp(k.sales)}, with ROAS at ${roasFmt(k.roas)}.` });
    } else {
      cards.push({ tone: "watch", title: "Sales not yet growing", body: `Panasonic sales at ${rp(k.sales)}${dSales != null ? ` (${pct(dSales)} vs prior period)` : ""}. Worth tracing the driver at the dealer and SKU level.` });
    }
    cards.push(atcRate >= 5
      ? { tone: "insight", title: "Top-of-funnel is healthy", body: `Add-to-cart ratio is ${pct(atcRate)} from ${cnt(k.traffic)} visits — interest is strengthening ahead of checkout.` }
      : { tone: "watch", title: "Top-of-funnel is thin", body: `Add-to-cart ratio is only ${pct(atcRate)} from ${cnt(k.traffic)} visits — worth checking traffic quality or listing relevance.` });
    cards.push(dGmv != null && dSales != null && dGmv > dSales
      ? { tone: "watch", title: "Share slipped despite growth", body: `Total dealer store sales grew faster (${pct(dGmv)}) than Panasonic (${pct(dSales)}), putting Panasonic's share at ${pct(shareFrac * 100)}. Other brands grew more — worth checking why.` }
      : { tone: "insight", title: `Panasonic share ${pct(shareFrac * 100)}`, body: `Panasonic accounted for ${pct(shareFrac * 100)} of total dealer store sales (${rp(k.gmv)}) this period.` });
    cards.push(weak > 0
      ? { tone: "watch", title: `${weak} dealers with ROAS below 1x`, body: `Of ${dealersLen} dealers, ${weak} spent more on ads than the Panasonic sales they generated. Prioritize support for these dealers.` }
      : { tone: "win", title: "Every dealer above 1x ROAS", body: `All ${dealersLen} dealers generated more Panasonic sales than ad spend this period.` });
    return cards;
  }
  if (lang === "jp") {
    if (dSales != null && dAds != null && dSales > 0 && dAds < 0) {
      cards.push({ tone: "win", title: "売上増加・広告費減少", body: `売上は${pct(dSales)}増加した一方、広告費は${pct(Math.abs(dAds))}減少しました。需要のオーガニック化が進み、広告予算がより効率的に機能しています — ROAS ${roasFmt(k.roas)}。` });
    } else if (dSales != null && dSales > 0) {
      cards.push({ tone: "win", title: "売上が成長", body: `パナソニックの売上は${pct(dSales)}増加し${rp(k.sales)}に達しました（ROAS ${roasFmt(k.roas)}）。` });
    } else {
      cards.push({ tone: "watch", title: "売上がまだ伸びていません", body: `パナソニックの売上は${rp(k.sales)}${dSales != null ? `（前期比${pct(dSales)}）` : ""}。販売店・SKUレベルでの要因分析が必要です。` });
    }
    cards.push(atcRate >= 5
      ? { tone: "insight", title: "ファネル上部は良好", body: `${cnt(k.traffic)}件の訪問に対しカート追加率は${pct(atcRate)}。チェックアウト前の関心が高まっています。` }
      : { tone: "watch", title: "ファネル上部が弱い", body: `${cnt(k.traffic)}件の訪問に対しカート追加率はわずか${pct(atcRate)}。トラフィックの質や商品情報の関連性を確認する必要があります。` });
    cards.push(dGmv != null && dSales != null && dGmv > dSales
      ? { tone: "watch", title: "成長はしているがシェアは低下", body: `販売店全体の売上（${pct(dGmv)}増）はパナソニック（${pct(dSales)}増）より速く伸びており、パナソニックのシェアは${pct(shareFrac * 100)}となりました。他ブランドの伸びが大きいため要因確認が必要です。` }
      : { tone: "insight", title: `パナソニックのシェア ${pct(shareFrac * 100)}`, body: `今期、パナソニックは販売店の総売上（${rp(k.gmv)}）のうち${pct(shareFrac * 100)}を占めました。` });
    cards.push(weak > 0
      ? { tone: "watch", title: `ROAS 1倍未満の販売店 ${weak}店`, body: `${dealersLen}店舗中${weak}店舗で、広告費がパナソニック売上を上回りました。これらの販売店への支援を優先してください。` }
      : { tone: "win", title: "全販売店でROAS 1倍超", body: `今期、全${dealersLen}店舗でパナソニック売上が広告費を上回りました。` });
    return cards;
  }
  // id
  if (dSales != null && dAds != null && dSales > 0 && dAds < 0) {
    cards.push({ tone: "win", title: "Sales naik, biaya turun", body: `Penjualan naik ${pct(dSales)} sementara biaya iklan turun ${pct(Math.abs(dAds))}. Permintaan makin organik dan anggaran iklan bekerja lebih efisien — ROAS di ${roasFmt(k.roas)}.` });
  } else if (dSales != null && dSales > 0) {
    cards.push({ tone: "win", title: "Penjualan tumbuh", body: `Penjualan Panasonic naik ${pct(dSales)} menjadi ${rp(k.sales)} dengan ROAS ${roasFmt(k.roas)}.` });
  } else {
    cards.push({ tone: "watch", title: "Penjualan belum tumbuh", body: `Penjualan Panasonic ${rp(k.sales)}${dSales != null ? ` (${pct(dSales)} vs periode sebelumnya)` : ""}. Perlu penelusuran pemicu di level dealer dan SKU.` });
  }
  cards.push(atcRate >= 5
    ? { tone: "insight", title: "Funnel atas sehat", body: `Rasio tambah-ke-keranjang ${pct(atcRate)} dari ${cnt(k.traffic)} kunjungan. Minat menguat sebelum tahap checkout.` }
    : { tone: "watch", title: "Funnel atas tipis", body: `Rasio tambah-ke-keranjang hanya ${pct(atcRate)} dari ${cnt(k.traffic)} kunjungan — kualitas trafik atau relevansi listing perlu dicek.` });
  cards.push(dGmv != null && dSales != null && dGmv > dSales
    ? { tone: "watch", title: "Pangsa turun meski tumbuh", body: `Total toko dealer tumbuh lebih cepat (${pct(dGmv)}) dari Panasonic (${pct(dSales)}), sehingga pangsa Panasonic di ${pct(shareFrac * 100)}. Brand lain tumbuh lebih besar — perlu dicek pemicunya.` }
    : { tone: "insight", title: `Pangsa Panasonic ${pct(shareFrac * 100)}`, body: `Panasonic menyumbang ${pct(shareFrac * 100)} dari total penjualan toko dealer (${rp(k.gmv)}) pada periode ini.` });
  cards.push(weak > 0
    ? { tone: "watch", title: `${weak} dealer dengan ROAS di bawah 1x`, body: `Dari ${dealersLen} dealer, ${weak} membelanjakan iklan lebih besar dari penjualan Panasonic yang dihasilkan. Prioritaskan pendampingan di dealer ini.` }
    : { tone: "win", title: "Semua dealer ROAS di atas 1x", body: `Seluruh ${dealersLen} dealer menghasilkan penjualan Panasonic melebihi belanja iklannya pada periode ini.` });
  return cards;
}

export function buildActions(lang: Lang, weak: number, cnt: (n: number) => string, inCart: number): string[] {
  if (lang === "en") {
    return [
      "Protect efficiency — maintain / scale ad budget on dealers & SKUs proven to run above target ROAS.",
      `Close the cart gap — activate checkout vouchers & follow-up chat on ${cnt(inCart)} carts from this period.`,
      "Push the premium mix — feature Inverter and premium-series models to raise average order value.",
      weak > 0 ? `Support the ${weak} low-ROAS dealers — audit ad structure and pricing before adding budget.` : "Replicate the best-performing dealer's playbook with other dealers in the same city.",
    ];
  }
  if (lang === "jp") {
    return [
      "効率を維持 — 目標ROASを上回っている販売店・SKUの広告予算を維持・拡大する。",
      `カート離脱を減らす — 今期の${cnt(inCart)}件のカート追加に対し、チェックアウトクーポンやフォローアップチャットを実施する。`,
      "プレミアムミックスを強化 — インバーターおよびプレミアムシリーズを訴求し、平均注文単価を引き上げる。",
      weak > 0 ? `低ROASの${weak}店舗を支援 — 予算追加の前に広告構成と価格を見直す。` : "好調な販売店の施策を同一都市の他店舗に展開する。",
    ];
  }
  return [
    "Jaga efisiensi — pertahankan / scale anggaran iklan pada dealer & SKU yang terbukti selama ROAS di atas target.",
    `Tutup jeda keranjang — aktifkan voucher checkout & follow-up chat pada ${cnt(inCart)} keranjang periode ini.`,
    "Dorong mix premium — tonjolkan model Inverter & seri premium untuk menaikkan nilai pesanan rata-rata.",
    weak > 0 ? `Dampingi ${weak} dealer ber-ROAS rendah — audit struktur iklan dan harga sebelum menambah anggaran.` : "Replikasi pola dealer terbaik ke dealer lain di kota yang sama.",
  ];
}

export function periodOrAllLabel(lang: Lang, year: string, quarter: string, month: string, week: string | null): string {
  const t = BOD_T[lang];
  const parts = [
    month ? `${month} ${year ?? ""}`.trim()
      : quarter ? `${quarter} ${year ?? ""}`.trim()
      : year ? String(year)
      : t.scopeAllPeriod,
    week || null,
  ].filter(Boolean);
  return parts.join(" · ");
}
